/// <summary>
/// PricingAttribute of table <c>LogisticsPostalAddress</c> field Location.
/// </summary>
/// [GUPPricingMetadataDiscovery][GUPPricingAttributeSourceDiscovery(GUPPricingAttributeSource::Customer, GUPPricingAttributeSourceLevel::Header)]
internal class GUPPricingAttributeLogisticsPostalAddressLocation extends GUPPricingAttributeLogisticsPostalAddress implements GUPIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(LogisticsPostalAddress, Location);
}

    public Set getAllowedValues()
    {
        var                    ret = new Set(Types::Int64);
        LogisticsPostalAddress logisticsPostalAddress;

        while select logisticsPostalAddress
            group by Location
        {
            if (! ret.in(logisticsPostalAddress.Location))
            {
                ret.add(logisticsPostalAddress.Location);
            }
        }
        return ret;
    }

    protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
    {
        QueryBuildRange qbr;

        qbr = _qbds.addRange(fieldNum(LogisticsPostalAddress, Location));
        qbr.value(queryValue(_value));
    }
